SET local check_function_bodies = off;

CREATE TABLE "public"."mrh_accounts" (
  "id"                        bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "email"                     text                     NOT NULL,
  "last_name"                 text                     NOT NULL DEFAULT ''::text,
  "first_name"                text                     NOT NULL DEFAULT ''::text,
  "middle_initial"            text                     NOT NULL DEFAULT ''::text,
  "active"                    text                     NOT NULL DEFAULT 'FALSE'::text,
  "created_date"              text                     NOT NULL DEFAULT ''::text,
  "created_time"              text                     NOT NULL DEFAULT ''::text,
  "last_access_date"          text                     NOT NULL DEFAULT ''::text,
  "last_access_time"          text                     NOT NULL DEFAULT ''::text,
  "permanent_pdf_issuance_id" text,
  "legacy_metadata"           jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "updated_at"                timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "mrh_accounts_active_check" CHECK ((active = ANY (ARRAY['TRUE'::text, 'FALSE'::text, 'DENIED'::text, 'RESTRICTED'::text]))),
  CONSTRAINT "mrh_accounts_email_key" UNIQUE (email),
  CONSTRAINT "mrh_accounts_email_normalized" CHECK ((email = lower(email))),
  CONSTRAINT "mrh_accounts_email_valid" CHECK ((POSITION(('@'::text) IN (email)) > 1)),
  CONSTRAINT "mrh_accounts_permanent_pdf_issuance_id_key" UNIQUE (permanent_pdf_issuance_id),
  CONSTRAINT "mrh_accounts_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."mrh_accounts"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."mrh_accounts" FROM "anon", "authenticated";

