  "source_event_id"    text,
  "audit_event_id"     text,
  "legacy_source"      text,
  "legacy_row"         integer,
  "legacy_date"        text                     NOT NULL DEFAULT ''::text,
  "legacy_time"        text                     NOT NULL DEFAULT ''::text,
  "email"              text,
  "last_name"          text                     NOT NULL DEFAULT ''::text,
  "first_name"         text                     NOT NULL DEFAULT ''::text,
  "middle_initial"     text                     NOT NULL DEFAULT ''::text,
  "event"              text                     NOT NULL DEFAULT ''::text,
  "course_code"        text                     NOT NULL DEFAULT ''::text,
  "year"               text                     NOT NULL DEFAULT ''::text,
  "semester"           text                     NOT NULL DEFAULT ''::text,
  "category"           text                     NOT NULL DEFAULT ''::text,
  "course"             text                     NOT NULL DEFAULT ''::text,
  "resource"           text                     NOT NULL DEFAULT ''::text,
  "issuance_reference" text                     NOT NULL DEFAULT ''::text,
  "source_file_id"     text                     NOT NULL DEFAULT ''::text,
  "record"             jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "created_at"         timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "mrh_activity_logs_area_check" CHECK ((area = ANY (ARRAY['SIGN-IN'::text, 'LIBRARY'::text, 'SYLLABUS'::text, 'MODULES'::text, 'REVIEWERS'::text]))),
  CONSTRAINT "mrh_activity_logs_audit_event_id_key" UNIQUE (audit_event_id),
  CONSTRAINT "mrh_activity_logs_legacy_row_unique" UNIQUE (legacy_source, legacy_row),
  CONSTRAINT "mrh_activity_logs_pkey" PRIMARY KEY (id)
);

