CREATE TABLE "public"."mrh_rate_limit_state" (
  "scope"           text                       NOT NULL,
  "identity_hash"   text                       NOT NULL,
  "request_times"   timestamp with time zone[] NOT NULL DEFAULT ARRAY[]::timestamp WITH time zone[],
  "distinct_events" jsonb                      NOT NULL DEFAULT '{}'::jsonb,
  "updated_at"      timestamp with time zone   NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT "mrh_rate_limit_state_distinct_events_check" CHECK ((jsonb_typeof(distinct_events) = 'object'::text)),
  CONSTRAINT "mrh_rate_limit_state_identity_hash_check" CHECK ((identity_hash ~ '^[0-9a-f]{64}$'::text)),
  CONSTRAINT "mrh_rate_limit_state_pkey" PRIMARY KEY (scope, identity_hash),
  CONSTRAINT "mrh_rate_limit_state_scope_check" CHECK ((scope = ANY (ARRAY['deck_password'::text, 'reviewer_pdf'::text, 'reviewer_pdf_probe'::text])))
);

