CREATE OR REPLACE FUNCTION public.mrh_apply_rate_limit (
  p_scope         text,
  p_identity_hash text,
  p_event_hash    text    DEFAULT NULL::text,
  p_consume       boolean DEFAULT true
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'pg_catalog', 'public', 'pg_temp'
  AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_window_seconds integer;
  v_max_requests integer;
  v_distinct_window_seconds integer := 0;
  v_max_distinct integer := 0;
  v_requests timestamptz[];
  v_events jsonb;
  v_distinct_count integer := 0;
  v_is_new boolean := false;
  v_allowed boolean := false;
  v_alert boolean := false;
  v_reason text := '';
BEGIN
  IF p_scope IS NULL OR p_scope NOT IN ('deck_password', 'reviewer_pdf', 'reviewer_pdf_probe') THEN
    RAISE EXCEPTION 'Invalid rate-limit scope' USING ERRCODE = '22023';
  END IF;
  IF p_identity_hash IS NULL OR p_identity_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Invalid rate-limit identity hash' USING ERRCODE = '22023';
  END IF;
  IF p_scope IN ('reviewer_pdf', 'reviewer_pdf_probe')
     AND (p_event_hash IS NULL OR p_event_hash !~ '^[0-9a-f]{64}$') THEN
    RAISE EXCEPTION 'Invalid protected-resource hash' USING ERRCODE = '22023';
  END IF;

  IF p_scope = 'deck_password' THEN
    v_window_seconds := 60;
    v_max_requests := 20;
  ELSIF p_scope = 'reviewer_pdf' THEN
    v_window_seconds := 600;
    v_max_requests := 30;
    v_distinct_window_seconds := 3600;
    v_max_distinct := 20;
  ELSE
    v_window_seconds := 600;
    v_max_requests := 2147483647;
    v_distinct_window_seconds := 600;
    v_max_distinct := 5;
  END IF;

  INSERT INTO public.mrh_rate_limit_state (scope, identity_hash)
  VALUES (p_scope, p_identity_hash)
  ON CONFLICT (scope, identity_hash) DO NOTHING;

  SELECT request_times, distinct_events
    INTO v_requests, v_events
  FROM public.mrh_rate_limit_state
  WHERE scope = p_scope AND identity_hash = p_identity_hash
  FOR UPDATE;

  SELECT COALESCE(array_agg(ts ORDER BY ts), ARRAY[]::timestamptz[])
    INTO v_requests
  FROM unnest(COALESCE(v_requests, ARRAY[]::timestamptz[])) AS recent(ts)
  WHERE ts > v_now - make_interval(secs => v_window_seconds);

  v_events := COALESCE(v_events, '{}'::jsonb);
  IF p_scope IN ('reviewer_pdf', 'reviewer_pdf_probe') THEN
    SELECT COALESCE(jsonb_object_agg(e.key, e.value), '{}'::jsonb)
      INTO v_events
    FROM jsonb_each(v_events) AS e(key, value)
    WHERE CASE
      WHEN jsonb_typeof(e.value) = 'number'
        AND (e.value #>> '{}') ~ '^[0-9]+(\.[0-9]+)?$'
      THEN (e.value #>> '{}')::numeric > EXTRACT(EPOCH FROM v_now) - v_distinct_window_seconds
      ELSE false
    END;
    SELECT count(*)::integer INTO v_distinct_count FROM jsonb_object_keys(v_events);
    v_is_new := NOT (v_events ? p_event_hash);
  END IF;

  IF p_scope = 'deck_password' THEN
    IF cardinality(v_requests) >= v_max_requests THEN
      v_allowed := false;
      v_reason := 'request_window';
    ELSE
      v_allowed := true;
      IF p_consume THEN v_requests := array_append(v_requests, v_now); END IF;
    END IF;
  ELSIF p_scope = 'reviewer_pdf' THEN
    IF cardinality(v_requests) >= v_max_requests THEN
      v_allowed := false;
      v_reason := 'request_window';
    ELSIF v_is_new AND v_distinct_count >= v_max_distinct THEN
      v_allowed := false;
      v_reason := 'distinct_window';
    ELSE
      v_allowed := true;
      IF p_consume THEN
        v_requests := array_append(v_requests, v_now);
        IF v_is_new THEN
          v_events := v_events || jsonb_build_object(p_event_hash, EXTRACT(EPOCH FROM v_now));
          v_distinct_count := v_distinct_count + 1;
          v_alert := v_distinct_count = 12;
        END IF;
      END IF;
    END IF;
  ELSE
    -- Store no more than five distinct resource hashes. Once the threshold is
    -- reached, return the signal again so restriction can be retried safely.
    v_allowed := true;
    IF p_consume AND v_is_new AND v_distinct_count < v_max_distinct THEN
      v_events := v_events || jsonb_build_object(p_event_hash, EXTRACT(EPOCH FROM v_now));
      v_distinct_count := v_distinct_count + 1;
    END IF;
    v_alert := v_distinct_count >= v_max_distinct;
  END IF;

  UPDATE public.mrh_rate_limit_state
  SET request_times = v_requests,
      distinct_events = v_events,
      updated_at = v_now
  WHERE scope = p_scope AND identity_hash = p_identity_hash;

  RETURN jsonb_build_object(
    'allowed', v_allowed,
    'code', CASE WHEN v_allowed THEN '' ELSE 'RATE_LIMITED' END,
    'reason', v_reason,
    'requestCount', cardinality(v_requests),
    'distinctCount', v_distinct_count,
    'alertThresholdReached', v_alert
  );
END;
$function$;

REVOKE ALL ON FUNCTION "public"."mrh_apply_rate_limit"(text, text, text, boolean) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.mrh_cleanup_rate_limit_state()
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'pg_catalog', 'public', 'pg_temp'
  AS $function$
DECLARE
  v_deleted bigint;
BEGIN
  DELETE FROM public.mrh_rate_limit_state
  WHERE updated_at < clock_timestamp() - INTERVAL '7 days';
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$function$;

REVOKE ALL ON FUNCTION "public"."mrh_cleanup_rate_limit_state"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.mrh_record_reviewer_pdf_access (
  p_email            text,
  p_audit_event_id   text,
  p_last_access_date text,
  p_last_access_time text,
  p_updated_at       timestamp with time zone,
  p_row              jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'pg_catalog'
  AS $function$
DECLARE
  v_activity public.mrh_activity_logs;
  v_account_patch public.mrh_accounts;
  v_inserted_audit_event_id text;
  v_account_rows integer := 0;
BEGIN
  IF p_email IS NULL OR lower(trim(p_email)) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
    RAISE EXCEPTION 'A valid verified account email is required.' USING ERRCODE = '22023';
  END IF;
  IF p_audit_event_id IS NULL OR p_audit_event_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'A valid PDF audit event UUID is required.' USING ERRCODE = '22023';
  END IF;
  IF p_row IS NULL
     OR jsonb_typeof(p_row) IS DISTINCT FROM 'object'
     OR p_row->>'area' IS DISTINCT FROM 'REVIEWERS'
     OR p_row->>'email' IS NULL
     OR lower(p_row->>'email') IS DISTINCT FROM lower(trim(p_email))
     OR p_row->>'audit_event_id' IS DISTINCT FROM p_audit_event_id
     OR coalesce(p_row->>'event', '') NOT IN ('PROTECTED_PDF_VIEW', 'PROTECTED_PDF_DOWNLOAD_ISSUED', 'PDF_DOWNLOAD') THEN
    RAISE EXCEPTION 'The protected-PDF audit payload is invalid.' USING ERRCODE = '22023';
  END IF;

  -- jsonb_populate_record casts values using the actual installed table column
  -- types, so this function does not assume whether legacy fields are text,
  -- date/time, UUID, JSON, or JSONB.
  v_activity := jsonb_populate_record(NULL::public.mrh_activity_logs, p_row);

  INSERT INTO public.mrh_activity_logs (
    area,
    source_event_id,
    audit_event_id,
    legacy_date,
    legacy_time,
    email,
    last_name,
    first_name,
    middle_initial,
    event,
    course_code,
    year,
    semester,
    category,
    course,
    resource,
    issuance_reference,
    source_file_id,
    record
  ) VALUES (
    v_activity.area,
    v_activity.source_event_id,
    v_activity.audit_event_id,
    v_activity.legacy_date,
    v_activity.legacy_time,
    v_activity.email,
    v_activity.last_name,
    v_activity.first_name,
    v_activity.middle_initial,
    v_activity.event,
    v_activity.course_code,
    v_activity.year,
    v_activity.semester,
    v_activity.category,
    v_activity.course,
    v_activity.resource,
    v_activity.issuance_reference,
    v_activity.source_file_id,
    v_activity.record
  )
  ON CONFLICT DO NOTHING
  RETURNING audit_event_id::text INTO v_inserted_audit_event_id;

  IF v_inserted_audit_event_id IS NULL THEN
    IF EXISTS (
      SELECT 1
      FROM public.mrh_activity_logs a
      WHERE a.audit_event_id::text = p_audit_event_id
    ) THEN
      RETURN jsonb_build_object(
        'ok', true,
        'duplicate', true,
        'audit_inserted', false,
        'account_updated', false
      );
    END IF;
    RAISE EXCEPTION 'The PDF audit row conflicted with another database constraint.' USING ERRCODE = '23505';
  END IF;

  v_account_patch := jsonb_populate_record(
    NULL::public.mrh_accounts,
    jsonb_build_object(
      'last_access_date', p_last_access_date,
      'last_access_time', p_last_access_time,
      'updated_at', p_updated_at
    )
  );

  UPDATE public.mrh_accounts
     SET last_access_date = v_account_patch.last_access_date,
         last_access_time = v_account_patch.last_access_time,
         updated_at = v_account_patch.updated_at
   WHERE email = lower(trim(p_email));
  GET DIAGNOSTICS v_account_rows = ROW_COUNT;

  IF v_account_rows > 1 THEN
    RAISE EXCEPTION 'More than one account row matched the verified email.' USING ERRCODE = '21000';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'duplicate', false,
    'audit_inserted', true,
    'account_updated', v_account_rows = 1
  );
END;
$function$;

REVOKE ALL ON FUNCTION "public"."mrh_record_reviewer_pdf_access"(text, text, text, text, timestamp WITH time zone, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.mrh_set_updated_at()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
  RETURNS event_trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'pg_catalog'
  AS $function$
DECLARE
  cmd record;
  tbl name;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid;
        EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

